CREATE TABLE IF NOT EXISTS schema_migrations (version TEXT PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS plans (id TEXT PRIMARY KEY, name TEXT NOT NULL, price_cents INTEGER NOT NULL CHECK(price_cents>=0), modules TEXT NOT NULL, equipment_limit INTEGER NOT NULL CHECK(equipment_limit>0), user_limit INTEGER NOT NULL CHECK(user_limit>0), active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS tenants (id TEXT PRIMARY KEY, name TEXT NOT NULL, timezone TEXT NOT NULL DEFAULT 'America/Sao_Paulo', demo INTEGER NOT NULL DEFAULT 0 CHECK(demo IN(0,1)), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS subscriptions (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL UNIQUE REFERENCES tenants(id), plan_id TEXT NOT NULL REFERENCES plans(id), status TEXT NOT NULL CHECK(status IN('trial','active','suspended','cancelled')), trial_until TEXT, started_at TEXT NOT NULL, ended_at TEXT);
CREATE TABLE IF NOT EXISTS subscription_history (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), snapshot TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, tenant_id TEXT REFERENCES tenants(id), name TEXT NOT NULL, email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN('EWS','OWNER','MANAGER','TECH','VIEWER')), active INTEGER NOT NULL DEFAULT 1, mfa_secret TEXT, mfa_enabled INTEGER NOT NULL DEFAULT 0, mfa_last_step INTEGER NOT NULL DEFAULT -1, created_at TEXT NOT NULL, CHECK((role='EWS' AND tenant_id IS NULL) OR (role<>'EWS' AND tenant_id IS NOT NULL)));
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf TEXT NOT NULL, expires_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS auth_tokens (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind TEXT NOT NULL CHECK(kind IN('invite','reset')), expires_at TEXT NOT NULL, used_at TEXT);
CREATE TABLE IF NOT EXISTS units (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, address TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS barns (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), unit_id TEXT NOT NULL, name TEXT NOT NULL, capacity INTEGER NOT NULL CHECK(capacity>=0), birds INTEGER NOT NULL CHECK(birds>=0 AND birds<=capacity), created_at TEXT NOT NULL, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,unit_id) REFERENCES units(tenant_id,id));
CREATE TABLE IF NOT EXISTS flocks (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), barn_id TEXT NOT NULL, name TEXT NOT NULL, birds INTEGER NOT NULL CHECK(birds>=0), starts_on TEXT NOT NULL, ends_on TEXT, created_at TEXT NOT NULL, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,barn_id) REFERENCES barns(tenant_id,id));
CREATE TABLE IF NOT EXISTS equipment (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), barn_id TEXT NOT NULL, name TEXT NOT NULL, category TEXT NOT NULL, model TEXT NOT NULL DEFAULT '', reference_hours DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(reference_hours>=0), schedule_hours DOUBLE PRECISION NOT NULL DEFAULT 24 CHECK(schedule_hours>0 AND schedule_hours<=24), notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,barn_id) REFERENCES barns(tenant_id,id));
CREATE TABLE IF NOT EXISTS gateways (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, token_hash TEXT NOT NULL UNIQUE, active INTEGER NOT NULL DEFAULT 1, last_seen TEXT, last_error TEXT, created_at TEXT NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS tags (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), equipment_id TEXT NOT NULL, gateway_id TEXT NOT NULL, name TEXT NOT NULL, unit TEXT NOT NULL, kind TEXT NOT NULL CHECK(kind IN('temperature','state','hours','cycles','kwh','humidity','power')), minimum DOUBLE PRECISION NOT NULL DEFAULT -100, maximum DOUBLE PRECISION NOT NULL DEFAULT 1000000000, stale_seconds INTEGER NOT NULL DEFAULT 120 CHECK(stale_seconds>=10), created_at TEXT NOT NULL, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,equipment_id) REFERENCES equipment(tenant_id,id), FOREIGN KEY(tenant_id,gateway_id) REFERENCES gateways(tenant_id,id));
CREATE TABLE IF NOT EXISTS measurements (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), gateway_id TEXT NOT NULL, tag_id TEXT NOT NULL, sequence BIGINT NOT NULL CHECK(sequence>=0), value DOUBLE PRECISION NOT NULL, unit TEXT NOT NULL, quality TEXT NOT NULL CHECK(quality IN('GOOD','UNCERTAIN','BAD')), source TEXT NOT NULL CHECK(source IN('MEASURED','MANUAL','IMPORTED','SIMULATED')), observed_at TEXT NOT NULL, received_at TEXT NOT NULL, UNIQUE(gateway_id,sequence), FOREIGN KEY(tenant_id,tag_id) REFERENCES tags(tenant_id,id), FOREIGN KEY(tenant_id,gateway_id) REFERENCES gateways(tenant_id,id));
CREATE INDEX IF NOT EXISTS measurements_lookup ON measurements(tenant_id,tag_id,observed_at);
CREATE INDEX IF NOT EXISTS measurements_retention ON measurements(observed_at);
CREATE TABLE IF NOT EXISTS tag_latest (tag_id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL, value DOUBLE PRECISION NOT NULL, quality TEXT NOT NULL, source TEXT NOT NULL, observed_at TEXT NOT NULL, FOREIGN KEY(tenant_id,tag_id) REFERENCES tags(tenant_id,id));
CREATE TABLE IF NOT EXISTS hourly_metrics (tenant_id TEXT NOT NULL, tag_id TEXT NOT NULL, hour TEXT NOT NULL, source TEXT NOT NULL, quality TEXT NOT NULL, count BIGINT NOT NULL, sum DOUBLE PRECISION NOT NULL, minimum DOUBLE PRECISION NOT NULL, maximum DOUBLE PRECISION NOT NULL, PRIMARY KEY(tag_id,hour,source,quality), FOREIGN KEY(tenant_id,tag_id) REFERENCES tags(tenant_id,id));
CREATE TABLE IF NOT EXISTS alert_rules (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), tag_id TEXT NOT NULL, name TEXT NOT NULL, threshold DOUBLE PRECISION NOT NULL, hysteresis DOUBLE PRECISION NOT NULL DEFAULT 1 CHECK(hysteresis>=0), duration_seconds INTEGER NOT NULL DEFAULT 60 CHECK(duration_seconds>=0), severity TEXT NOT NULL CHECK(severity IN('info','warning','critical')), silence_until TEXT, active INTEGER NOT NULL DEFAULT 1, pending_since TEXT, last_evaluated_at TEXT, latched INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,tag_id) REFERENCES tags(tenant_id,id));
CREATE TABLE IF NOT EXISTS incidents (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), equipment_id TEXT NOT NULL, rule_id TEXT, title TEXT NOT NULL, severity TEXT NOT NULL CHECK(severity IN('info','warning','critical')), status TEXT NOT NULL CHECK(status IN('open','acknowledged','closed')), assignee TEXT NOT NULL DEFAULT '', action TEXT NOT NULL DEFAULT '', source TEXT NOT NULL, opened_at TEXT NOT NULL, closed_at TEXT, created_at TEXT NOT NULL, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,equipment_id) REFERENCES equipment(tenant_id,id), FOREIGN KEY(tenant_id,rule_id) REFERENCES alert_rules(tenant_id,id));
CREATE UNIQUE INDEX IF NOT EXISTS incidents_one_active ON incidents(rule_id) WHERE status <> 'closed' AND rule_id IS NOT NULL;
CREATE TABLE IF NOT EXISTS maintenance_plans (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), equipment_id TEXT NOT NULL, name TEXT NOT NULL, every_hours DOUBLE PRECISION NOT NULL CHECK(every_hours>0), next_hours DOUBLE PRECISION NOT NULL CHECK(next_hours>=0), checklist TEXT NOT NULL DEFAULT '[]', created_at TEXT NOT NULL, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,equipment_id) REFERENCES equipment(tenant_id,id));
CREATE TABLE IF NOT EXISTS work_orders (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), equipment_id TEXT NOT NULL, title TEXT NOT NULL, assignee TEXT NOT NULL DEFAULT '', priority TEXT NOT NULL CHECK(priority IN('low','normal','high','critical')), status TEXT NOT NULL CHECK(status IN('open','assigned','in_progress','completed')), due_on TEXT NOT NULL, checklist TEXT NOT NULL DEFAULT '[]', report TEXT NOT NULL DEFAULT '', parts_cents INTEGER NOT NULL DEFAULT 0 CHECK(parts_cents>=0), labor_cents INTEGER NOT NULL DEFAULT 0 CHECK(labor_cents>=0), duration_minutes INTEGER NOT NULL DEFAULT 0 CHECK(duration_minutes>=0), completed_at TEXT, created_at TEXT NOT NULL, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,equipment_id) REFERENCES equipment(tenant_id,id));
CREATE TABLE IF NOT EXISTS downtimes (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), equipment_id TEXT NOT NULL, starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, reason TEXT NOT NULL, failure INTEGER NOT NULL DEFAULT 1, scheduled_minutes INTEGER NOT NULL CHECK(scheduled_minutes>0), source TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(tenant_id,id), CHECK(ends_at>starts_at), FOREIGN KEY(tenant_id,equipment_id) REFERENCES equipment(tenant_id,id));
CREATE TABLE IF NOT EXISTS meters (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), barn_id TEXT, name TEXT NOT NULL, serial TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,barn_id) REFERENCES barns(tenant_id,id));
CREATE TABLE IF NOT EXISTS tariffs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, rate_micros INTEGER NOT NULL CHECK(rate_micros>=0), starts_on TEXT NOT NULL, ends_on TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(tenant_id,id), CHECK(ends_on>=starts_on));
CREATE TABLE IF NOT EXISTS energy_readings (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), meter_id TEXT NOT NULL, day TEXT NOT NULL, kwh DOUBLE PRECISION NOT NULL CHECK(kwh>=0), demand_kw DOUBLE PRECISION CHECK(demand_kw>=0), source TEXT NOT NULL CHECK(source IN('MEASURED','MANUAL','IMPORTED','SIMULATED')), evidence TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(tenant_id,id), UNIQUE(meter_id,day), FOREIGN KEY(tenant_id,meter_id) REFERENCES meters(tenant_id,id));
CREATE TABLE IF NOT EXISTS invoices (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, period_start TEXT NOT NULL, period_end TEXT NOT NULL, kwh DOUBLE PRECISION NOT NULL CHECK(kwh>=0), total_cents INTEGER NOT NULL CHECK(total_cents>=0), source TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(tenant_id,id), CHECK(period_end>=period_start));
CREATE TABLE IF NOT EXISTS production (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), barn_id TEXT NOT NULL, day TEXT NOT NULL, eggs INTEGER NOT NULL CHECK(eggs>=0), birds INTEGER NOT NULL CHECK(birds>0), source TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(tenant_id,id), UNIQUE(barn_id,day), FOREIGN KEY(tenant_id,barn_id) REFERENCES barns(tenant_id,id));
CREATE TABLE IF NOT EXISTS costs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), barn_id TEXT, name TEXT NOT NULL, day TEXT NOT NULL, category TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>=0), source TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(tenant_id,id), FOREIGN KEY(tenant_id,barn_id) REFERENCES barns(tenant_id,id));
CREATE TABLE IF NOT EXISTS opportunities (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), name TEXT NOT NULL, category TEXT NOT NULL CHECK(category IN('alert','estimated','verified')), amount_cents INTEGER NOT NULL DEFAULT 0 CHECK(amount_cents>=0), baseline_start TEXT, baseline_end TEXT, comparison_start TEXT, comparison_end TEXT, methodology TEXT NOT NULL DEFAULT '', evidence TEXT NOT NULL DEFAULT '', adjustments TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), title TEXT NOT NULL, body TEXT NOT NULL, read_at TEXT, created_at TEXT NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS tickets (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), title TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('open','in_progress','closed')), reply TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS charges (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), description TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0), due_on TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN('pending','paid','void')), paid_at TEXT, reference TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, UNIQUE(tenant_id,id));
CREATE TABLE IF NOT EXISTS billing_events (id TEXT PRIMARY KEY, provider TEXT NOT NULL, payload_hash TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS leads (id TEXT PRIMARY KEY, name TEXT NOT NULL, company TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, message TEXT NOT NULL, consent INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'new', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, tenant_id TEXT REFERENCES tenants(id), user_id TEXT, action TEXT NOT NULL, entity TEXT NOT NULL, entity_id TEXT NOT NULL, details TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_lookup ON audit_logs(tenant_id,created_at);
CREATE TABLE IF NOT EXISTS outbox (id TEXT PRIMARY KEY, tenant_id TEXT REFERENCES tenants(id), recipient TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', attempts INTEGER NOT NULL DEFAULT 0, next_attempt_at TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS units_tenant ON units(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS barns_tenant ON barns(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS flocks_tenant ON flocks(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS equipment_tenant ON equipment(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS gateways_tenant ON gateways(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS tags_tenant ON tags(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS alert_rules_tenant ON alert_rules(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS incidents_tenant ON incidents(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS maintenance_plans_tenant ON maintenance_plans(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS work_orders_tenant ON work_orders(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS downtimes_tenant ON downtimes(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS meters_tenant ON meters(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS tariffs_tenant ON tariffs(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS energy_readings_tenant ON energy_readings(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS invoices_tenant ON invoices(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS production_tenant ON production(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS costs_tenant ON costs(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS opportunities_tenant ON opportunities(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS notifications_tenant ON notifications(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS tickets_tenant ON tickets(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS charges_tenant ON charges(tenant_id,created_at);
CREATE INDEX IF NOT EXISTS energy_readings_day ON energy_readings(tenant_id,day);
CREATE INDEX IF NOT EXISTS production_day ON production(tenant_id,day);
CREATE INDEX IF NOT EXISTS costs_day ON costs(tenant_id,day);

CREATE TABLE IF NOT EXISTS operation_logs (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), equipment_id TEXT NOT NULL, day TEXT NOT NULL, scheduled_minutes INTEGER NOT NULL CHECK(scheduled_minutes>0 AND scheduled_minutes<=1440), operating_minutes INTEGER NOT NULL CHECK(operating_minutes>=0 AND operating_minutes<=scheduled_minutes), failure_count INTEGER NOT NULL CHECK(failure_count>=0), coverage_percent DOUBLE PRECISION NOT NULL CHECK(coverage_percent>=0 AND coverage_percent<=100), source TEXT NOT NULL, evidence TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(tenant_id,id), UNIQUE(equipment_id,day), FOREIGN KEY(tenant_id,equipment_id) REFERENCES equipment(tenant_id,id));
CREATE INDEX IF NOT EXISTS operation_logs_tenant_day ON operation_logs(tenant_id,day);
CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY, tenant_id TEXT NOT NULL REFERENCES tenants(id), work_order_id TEXT NOT NULL, name TEXT NOT NULL, media_type TEXT NOT NULL, content_base64 TEXT NOT NULL, size_bytes INTEGER NOT NULL, created_at TEXT NOT NULL, FOREIGN KEY(tenant_id,work_order_id) REFERENCES work_orders(tenant_id,id));
CREATE INDEX IF NOT EXISTS attachments_tenant ON attachments(tenant_id,work_order_id);
